using SixLabors.ImageSharp.Formats.Av1.Bitstream;
using SixLabors.ImageSharp.Formats.Av1.Obu;

namespace SixLabors.ImageSharp.Codecs.Av1.Tests;

/// <summary>
/// End-to-end intra decode of a real 128x128 all-intra clip that uses PARTITION_SPLIT, TX_MODE_SELECT
/// and a 2x2 grid of TX_16X16 transforms per 32x32 block. The reconstruction is compared against
/// dav1d 1.4.1's decoded output and matches it bit-exactly.
/// </summary>
public class Av1MultiBlockDecodeTests
{
    private static readonly byte[] SequencePayload = Convert.FromHexString("1819bfff6c02");

    private static readonly byte[] FramePayload = Convert.FromHexString(
        "1320000016000010b56bc38e978a0c0750ae75c7d26176605ce99456713e51845b945b1eb9bed91483640cab35294167d12477847d589cb9e653b78549566f0b5732c2e3f6b6a91bb0863644dbe492724bb2de3b336e758ef6d6e087006e8b2770");

    [Fact]
    public void DecodeTile_RealMultiBlockStream_MatchesDav1d()
    {
        ObuSequenceHeader sequenceHeader = ObuSequenceHeader.Parse(SequencePayload);
        Av1BitStreamReader reader = new(FramePayload);
        ObuFrameHeader frameHeader = ObuFrameHeader.ParseIntra(ref reader, sequenceHeader);

        int tileGroupStart = (frameHeader.EndBitPosition + 7) >> 3;
        ObuTileGroup tileGroup = ObuTileGroup.Parse(FramePayload.AsSpan(tileGroupStart), frameHeader);
        (int offset, int length) = tileGroup.GetTile(0);

        Av1TileDecoder decoder = new(sequenceHeader, frameHeader);
        decoder.DecodeTile(FramePayload.AsMemory(tileGroupStart + offset, length));

        Assert.Equal(128, decoder.Luma.Width);
        Assert.Equal(128, decoder.Luma.Height);
        Assert.All(decoder.ChromaU.Samples, s => Assert.Equal(128, s));
        Assert.All(decoder.ChromaV.Samples, s => Assert.Equal(128, s));

        byte[] reference = Convert.FromBase64String(Dav1dLumaBase64);
        Assert.True(decoder.Luma.Samples.AsSpan().SequenceEqual(reference), "Reconstructed luma differs from the dav1d reference.");
    }

    private const string Dav1dLumaBase64 =
        "";
}
